<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {NButton,NAlert,NTag} from 'naive-ui'
import {ShieldCheck,LogOut,RefreshCw} from '@lucide/vue'
import {APIError,csrfKey} from '../api/client'
import {useAuth} from '../features/auth/store'
const auth=useAuth(),router=useRouter(),route=useRoute(),error=ref(''),busy=ref(false)
let timer:ReturnType<typeof setInterval>|undefined
async function refresh(){try{if(!await auth.refresh())await router.replace('/login');else error.value=''}catch(e){error.value=e instanceof Error?e.message:'会话验证失败。'}}
async function logout(){busy.value=true;error.value='';try{if(!sessionStorage.getItem(csrfKey)){error.value='此标签页缺少安全校验资料，请重新登录后退出。';return}await auth.logout();await router.replace('/login')}catch(e){if(e instanceof APIError&&e.status===401){if(await auth.refresh()){error.value='退出被拒绝，会话仍有效。请重新登录后再试。'}else{await router.replace('/login')}}else error.value=e instanceof Error?e.message:'退出失败。'}finally{busy.value=false}}
onMounted(()=>{timer=setInterval(()=>void refresh(),15000);window.addEventListener('focus',refresh)})
onUnmounted(()=>{if(timer)clearInterval(timer);window.removeEventListener('focus',refresh)})
</script>
<template><div class="min-h-screen"><header class="bg-white border-b border-emerald-950/10 px-6 md:px-12 py-5 flex justify-between items-center gap-4"><div class="brand"><shield-check :size="26"/> GATEBEAM</div><n-button @click="logout" :loading="busy"><template #icon><log-out :size="16"/></template>退出登录</n-button></header><nav class="console-nav"><router-link to="/">身份</router-link><router-link to="/console/sites">站点配置</router-link><router-link to="/console/targets">目标组</router-link><router-link to="/console/releases">发布审阅</router-link><router-link to="/console/certificates">证书管理</router-link><router-link to="/console/credentials">凭据管理</router-link><router-link to="/console/identities">内部身份</router-link><router-link to="/console/overview">统计概览</router-link><router-link to="/console/logs">历史日志</router-link><router-link to="/console/alerts">告警通知</router-link><router-link to="/console/backups">备份恢复</router-link><router-link to="/console/accounts">账号管理</router-link><router-link to="/console/audit">审计记录</router-link></nav><main class="max-w-5xl mx-auto px-6 py-12"><n-alert v-if="error" type="error" role="alert" class="error">{{error}} <router-link to="/login">重新登录</router-link></n-alert><router-view v-if="route.path!=='/'"/><template v-else><div class="text-sm muted mb-3">控制台 / 身份</div><h1>会话概览</h1><p class="muted mb-8">以下信息来自当前服务端会话。</p><section v-if="auth.actor" class="bg-white border border-emerald-950/10 rounded-2xl p-7"><div class="flex justify-between items-center gap-3"><h2 class="m-0">当前身份</h2><n-tag type="success" round>已认证</n-tag></div><dl class="grid gap-5 mt-7"><div><dt class="muted text-xs mb-1">用户 ID</dt><dd class="m-0 font-mono break-all">{{auth.actor.user_id}}</dd></div><div><dt class="muted text-xs mb-1">当前角色</dt><dd class="m-0">{{({admin:'管理员',readonly:'只读用户',editor:'编辑者',publisher:'发布者'} as Record<string,string>)[auth.actor.role] || auth.actor.role}}</dd></div><div><dt class="muted text-xs mb-1">认证方式</dt><dd class="m-0">{{auth.actor.credential_kind==='session'?'浏览器会话':auth.actor.credential_kind}}</dd></div></dl><n-button class="mt-7" @click="refresh"><template #icon><refresh-cw :size="16"/></template>重新验证会话</n-button></section></template></main></div></template>
